/**
 * A typed handle to an org group. Reference-only, same contract as
 * {@link UserRef} — exists so builders point at a group type-safely
 * instead of accepting a raw id string.
 */
export interface GroupRef {
    readonly id: string;
    readonly name?: string;
}
export declare function group(opts: {
    id: string;
    name?: string;
}): GroupRef;
